import gurobipy
from gurobipy import GRB
cutoff_date = '2026-03-12'
effective_records = {}
for family, records in CSVQA_DATA['logical_records'].items():
    best = {}
    best_rev = {}
    for rec in records:
        vals = rec['values']
        tenant = vals.get('tenant')
        if tenant != 'NORTH':
            continue
        eff_date = vals.get('effective_date')
        if eff_date is None or eff_date > cutoff_date:
            continue
        record_id = vals.get('record_id')
        rev = int(vals.get('revision', '0'))
        key = (tenant, record_id)
        if key not in best or rev > best_rev[key]:
            best[key] = rec
            best_rev[key] = rev
    seen = set()
    eff_list = []
    for rec in best.values():
        vals = rec['values']
        if vals.get('action') == 'DELETE':
            continue
        key = (vals.get('record_id'), int(vals.get('revision', '0')))
        if key in seen:
            continue
        seen.add(key)
        eff_list.append(rec)
    effective_records[family] = eff_list
benefit = {}
item_fee = {}
cat_fee = {}
cat_min = {}
cat_max = {}
auth = {}
min_lot = {}
max_order = {}
item_category = {}
usage = {}
capacity = {}
bundle_bonus = {}
incompatible = set()
requires = set()
for rec in effective_records.get('item', []):
    vals = rec['values']
    item_ref = vals['item_ref']
    benefit[item_ref] = 0
    item_fee[item_ref] = 0
    auth[item_ref] = int(vals['authorized'])
    min_lot[item_ref] = int(vals['minimum_lot'])
    max_order[item_ref] = int(vals['maximum_order'])
    item_category[item_ref] = vals['category']
for rec in effective_records.get('category', []):
    vals = rec['values']
    cat = vals['category']
    cat_fee[cat] = int(vals['activation_fee_cents'])
    cat_min[cat] = int(vals['minimum_quantity'])
    cat_max[cat] = int(vals['maximum_quantity'])
for rec in effective_records.get('benefit', []):
    vals = rec['values']
    item_ref = vals['item_ref']
    amt = int(vals['amount_cents'])
    benefit[item_ref] = benefit.get(item_ref, 0) + amt
for rec in effective_records.get('item_fee', []):
    vals = rec['values']
    item_ref = vals['item_ref']
    item_fee[item_ref] = int(vals['activation_fee_cents'])
for rec in effective_records.get('usage', []):
    vals = rec['values']
    item_ref = vals['item_ref']
    res = vals['resource']
    amt = int(vals['amount'])
    usage[item_ref, res] = usage.get((item_ref, res), 0) + amt
for rec in effective_records.get('capacity_ledger', []):
    vals = rec['values']
    res = vals['resource']
    amt = int(vals['amount'])
    capacity[res] = capacity.get(res, 0) + amt
for rec in effective_records.get('bundle', []):
    vals = rec['values']
    a = vals['item_a']
    b = vals['item_b']
    bonus = int(vals['bonus_cents'])
    key = tuple(sorted((a, b)))
    bundle_bonus[key] = bonus
for rec in effective_records.get('incompatible', []):
    vals = rec['values']
    a = vals['item_a']
    b = vals['item_b']
    incompatible.add(tuple(sorted((a, b))))
for rec in effective_records.get('requires', []):
    vals = rec['values']
    a = vals['item_ref']
    b = vals['prerequisite_ref']
    requires.add((a, b))
items = set(item_category.keys())
categories = set(cat_fee.keys())
resources = set(capacity.keys())
m = gurobipy.Model()
m.setParam('MIPGap', 1e-06)
x = {i: m.addVar(vtype=GRB.INTEGER, name=f'x_{i}') for i in items}
u = {i: m.addVar(vtype=GRB.BINARY, name=f'u_{i}') for i in items}
y = {c: m.addVar(vtype=GRB.BINARY, name=f'y_{c}') for c in categories}
w = {}
for (a, b), bonus in bundle_bonus.items():
    w[a, b] = m.addVar(vtype=GRB.BINARY, name=f'w_{a}_{b}')
m.update()
for i in items:
    max_ord = max_order.get(i, 0)
    min_lot_i = min_lot.get(i, 0)
    auth_i = auth.get(i, 0)
    if auth_i == 0:
        max_ord = 0
        min_lot_i = 0
    m.addConstr(x[i] <= max_ord * u[i], name=f'max_{i}')
    if auth_i > 0:
        m.addConstr(x[i] >= min_lot_i * u[i], name=f'min_{i}')
for c in categories:
    members = [i for i in items if item_category.get(i) == c]
    if members:
        m.addConstr(y[c] <= gurobipy.quicksum((u[i] for i in members)), name=f'cat_act_{c}')
for c in categories:
    members = [i for i in items if item_category.get(i) == c]
    if members:
        m.addConstr(gurobipy.quicksum((x[i] for i in members)) >= cat_min.get(c, 0), name=f'cat_min_{c}')
        m.addConstr(gurobipy.quicksum((x[i] for i in members)) <= cat_max.get(c, 0), name=f'cat_max_{c}')
for a, b in incompatible:
    m.addConstr(u[a] + u[b] <= 1, name=f'incomp_{a}_{b}')
for a, b in requires:
    m.addConstr(u[a] <= u[b], name=f'requires_{a}_{b}')
for (a, b), bonus in bundle_bonus.items():
    m.addConstr(w[a, b] <= u[a], name=f'w_le_a_{a}_{b}')
    m.addConstr(w[a, b] <= u[b], name=f'w_le_b_{a}_{b}')
    m.addConstr(w[a, b] >= u[a] + u[b] - 1, name=f'w_ge_{a}_{b}')
for r in resources:
    expr = gurobipy.quicksum((usage.get((i, r), 0) * x[i] for i in items))
    m.addConstr(expr <= capacity.get(r, 0), name=f'cap_{r}')
obj = gurobipy.quicksum((benefit.get(i, 0) * x[i] - item_fee.get(i, 0) * u[i] for i in items))
obj -= gurobipy.quicksum((cat_fee.get(c, 0) * y[c] for c in categories))
obj += gurobipy.quicksum((bundle_bonus.get((a, b), 0) * w[a, b] for a, b in bundle_bonus))
m.setObjective(obj, GRB.MAXIMIZE)
m.optimize()
